package com.motohub.next;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.Color;import org.json.*;import org.osmdroid.views.*;import org.osmdroid.views.overlay.*;import org.osmdroid.tileprovider.tilesource.TileSourceFactory;import org.osmdroid.util.GeoPoint;import java.util.*;import java.util.concurrent.*;
/** Full screen native map. REST snapshots every 5s, expiration checked every second. */
public final class GroupMapActivity extends Activity {
 MapView map;TextView status;String group;volatile boolean resumed;volatile SocialClient.Control control;final Handler ui=new Handler(Looper.getMainLooper());final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();ScheduledFuture<?> poll;List<LivePoint> points=new ArrayList<>();boolean centered;long epoch;
 final Runnable expire=new Runnable(){public void run(){if(!resumed)return;if(points.removeIf(p->p.expires<=System.currentTimeMillis()))draw();ui.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);group=getIntent().getStringExtra("group");try{UUID.fromString(group);}catch(Exception e){finish();return;}
  org.osmdroid.config.Configuration.getInstance().setUserAgentValue(getPackageName()+"/"+BuildConfig.VERSION_NAME);org.osmdroid.config.Configuration.getInstance().setOsmdroidBasePath(new java.io.File(getCacheDir(),"map"));org.osmdroid.config.Configuration.getInstance().setOsmdroidTileCache(new java.io.File(getCacheDir(),"map/tiles"));
  boolean dark=getIntent().getBooleanExtra("dark",false);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(dark?0xff0C141B:0xffFAFBFC);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets x=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(x.left,x.top,x.right,x.bottom);}else v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(12,8,12,8);Button back=new Button(this);back.setText("←");back.setContentDescription("뒤로 가기");back.setAllCaps(false);back.setOnClickListener(v->finish());bar.addView(back);TextView title=new TextView(this);title.setText(getIntent().getStringExtra("title"));title.setTextSize(20);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setTextColor(dark?Color.WHITE:0xff13212C);title.setPadding(14,0,0,0);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);status=new TextView(this);status.setTextSize(16);status.setTextColor(dark?0xffA1B1BE:0xff677886);status.setPadding(16,8,16,8);status.setText("서버 위치 확인 중 · 5초 주기");root.addView(status);
  map=new MapView(this);map.setTileSource(TileSourceFactory.MAPNIK);map.setMultiTouchControls(true);if(dark)map.getOverlayManager().getTilesOverlay().setColorFilter(org.osmdroid.views.overlay.TilesOverlay.INVERT_COLORS);map.getController().setZoom(2.0);map.getController().setCenter(new GeoPoint(0,0));root.addView(map,new LinearLayout.LayoutParams(-1,0,1));TextView attribution=new TextView(this);attribution.setText("© OpenStreetMap contributors · 공유 중인 실제 좌표만 표시");attribution.setTextSize(13);attribution.setTextColor(dark?Color.WHITE:Color.BLACK);root.addView(attribution);Button stop=new Button(this);stop.setText("내 위치 공유 중지");stop.setAllCaps(false);stop.setMinHeight(52);stop.setVisibility(Sharing.enabled?View.VISIBLE:View.GONE);stop.setOnClickListener(v->{Sharing.stop();status.setText(Sharing.status);stop.setVisibility(View.GONE);});root.addView(stop);
 }
 @Override protected void onResume(){super.onResume();if(map==null)return;resumed=true;epoch++;map.onResume();long e=epoch;poll=worker.scheduleWithFixedDelay(()->fetch(e),0,5,TimeUnit.SECONDS);ui.post(expire);}
 void fetch(long e){try{SocialClient.Control c=new SocialClient.Control();control=c;JSONArray rows=new JSONArray(SocialClient.INSTANCE.call("GET","/rest/v1/mh_positions?select=user_id,lat,lon,bearing,state,received_at,expires_at&group_id=eq."+group+"&limit=32",null,true,c));List<LivePoint> fresh=new ArrayList<>();for(int i=0;i<rows.length();i++)try{fresh.add(new LivePoint(rows.getJSONObject(i),System.currentTimeMillis()));}catch(Exception ignored){}ui.post(()->{if(!resumed||e!=epoch)return;points=fresh;draw();status.setText(points.isEmpty()?"현재 공유 중인 위치가 없어요.":points.size()+"명 · 5초 주기 갱신 · "+Sharing.status);});}catch(Exception ex){ui.post(()->{if(!resumed||e!=epoch)return;points.clear();draw();status.setText("위치를 확인하지 못했어요. 연결과 참가 권한을 확인하세요.");});}}
 void draw(){map.getOverlays().clear();for(LivePoint p:points){Marker marker=new Marker(map);marker.setPosition(new GeoPoint(p.lat,p.lon));marker.setTitle(SocialClient.INSTANCE.name(p.user)+" · "+p.label());marker.setSnippet((Double.isNaN(p.bearing)?"방향 확인 중":"방향 "+Math.round(p.bearing)+"°")+" · 갱신 "+p.time);marker.setRotation(Double.isNaN(p.bearing)?0:(float)-p.bearing);map.getOverlays().add(marker);}if(!centered&&!points.isEmpty()){map.getController().setZoom(15.0);map.getController().setCenter(new GeoPoint(points.get(0).lat,points.get(0).lon));centered=true;}map.invalidate();}
 @Override protected void onPause(){resumed=false;epoch++;ui.removeCallbacksAndMessages(null);if(poll!=null)poll.cancel(false);if(control!=null)control.cancel();if(map!=null){points.clear();map.getOverlays().clear();map.onPause();}super.onPause();}
 @Override protected void onDestroy(){worker.shutdownNow();if(map!=null)map.onDetach();super.onDestroy();}
}
